#![cfg(spawned_sim)]

const INPUT: &[u8] = include_bytes!("../regressions/transient_restarts_on_job_payload_cleanup.input");
const TAPE: &str = include_str!("../regressions/transient_restarts_on_job_payload_cleanup.tape");

/// The input under its own schedule and under its recorded tape.
#[test]
fn transient_restarts_on_job_payload_cleanup_tape() {
    spawned_fuzz::assert_passes_faults(INPUT, Some(TAPE));
}

/// The same operations under other simulator schedules.
#[spawned_macros::sim_test(seeds = 32)]
async fn transient_restarts_on_job_payload_cleanup_seeds(seed: u64) {
    spawned_fuzz::init();
    spawned_fuzz::run_body(spawned_fuzz::decode_faults(INPUT).unwrap(), seed).await;
}
